"""Unit tests for the parts of the action that need no runner and no guest."""

import json
import os
import sys
import tempfile
import unittest
import xml.etree.ElementTree as ET
from pathlib import Path
from unittest import mock

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
import qemu_tool_action as qta  # noqa: E402

# Verbatim from qemu-minimal v2.1.0, qemu/compose/rocm-golden.
INVENTORY = """---
# Generated by `qemu-tool gen-compose`. Do not edit.

all:
  vars:
    ansible_host: 127.0.0.1
    ansible_user: ubuntu
    ansible_ssh_common_args: >-
      -o StrictHostKeyChecking=no
      -o UserKnownHostsFile=/dev/null

  children:
    fleet:
      vars:
        fleet_guest_rocjitsu_image: "docker.io/x/rocjitsu:20261112"
        fleet_guest_prefix: 24
      hosts:
        rocm-golden-1:
          ansible_port: 2222
          fleet_guest_ip: 192.168.100.11
          fleet_guest_ernic_mac: 72:6f:63:6d:00:01
        rocm-golden-2:
          ansible_port: 2223
          fleet_guest_ip: 192.168.100.12
          fleet_guest_ernic_mac: 72:6f:63:6d:00:02
"""

# The shape helios-tray has: several NICs per guest.
INVENTORY_MULTI_NIC = """all:
  vars:
    ansible_host: 127.0.0.1
    ansible_user: ubuntu
  children:
    fleet:
      hosts:
        helios-1:
          ansible_port: 2322
          fleet_guest_ip: 192.168.100.11
          fleet_guest_nics:
            - index: 1
              mac: 72:6f:63:6d:00:01
              ip: 192.168.100.11
            - index: 2
              mac: 72:6f:63:6d:00:02
              ip: 192.168.100.12
"""


def inputs(**values):
    env = {f"INPUT_{key.upper().replace('_', '-')}": value
           for key, value in values.items()}
    return mock.patch.dict(os.environ, env, clear=False)


class Inventory(unittest.TestCase):
    def test_hosts_ports_and_addresses(self):
        shared, hosts = qta.parse_inventory(INVENTORY)
        self.assertEqual(shared, {
            "ansible_host": "127.0.0.1", "ansible_user": "ubuntu",
            "fleet_guest_rocjitsu_image": "docker.io/x/rocjitsu:20261112"})
        self.assertEqual([h["name"] for h in hosts],
                         ["rocm-golden-1", "rocm-golden-2"])
        self.assertEqual([h["ansible_port"] for h in hosts], ["2222", "2223"])
        self.assertEqual(hosts[1]["fleet_guest_ip"], "192.168.100.12")

    def test_fleet_vars_are_not_hosts(self):
        _, hosts = qta.parse_inventory(INVENTORY)
        self.assertNotIn("fleet_guest_prefix", [h["name"] for h in hosts])

    def test_every_nic_of_a_guest(self):
        _, hosts = qta.parse_inventory(INVENTORY_MULTI_NIC)
        self.assertEqual(len(hosts), 1)
        self.assertEqual(hosts[0]["nic_ips"],
                         ["192.168.100.11", "192.168.100.12"])
        self.assertEqual(hosts[0]["nics"][1], {
            "index": "2", "mac": "72:6f:63:6d:00:02", "ip": "192.168.100.12"})
        # The guest's own keys are not taken for a NIC's.
        self.assertEqual(hosts[0]["ansible_port"], "2322")
        self.assertEqual(hosts[0]["fleet_guest_ip"], "192.168.100.11")

    def test_the_guests_own_nic_is_the_one_qemu_tool_names(self):
        """Not simply the first: the first NIC may be off the mesh."""
        text = INVENTORY_MULTI_NIC.replace(
            "fleet_guest_ip: 192.168.100.11", "fleet_guest_ip: 192.168.100.12")
        with tempfile.TemporaryDirectory() as tmp:
            Path(tmp, "fleet-inventory.yml").write_text(text)
            vm = qta.build_manifest({"stack_dir": tmp, "key_dir": tmp,
                                     "stack_name": "x", "in_network": False})[0]
        self.assertEqual(vm["rdma_ip"], "192.168.100.12")
        self.assertEqual(vm["rdma_ips"], ["192.168.100.11", "192.168.100.12"])
        self.assertEqual(len(vm["nics"]), 2)

    def test_manifest_from_a_stack_directory(self):
        with tempfile.TemporaryDirectory() as tmp:
            stack, keys = Path(tmp, "ci"), Path(tmp, "keys")
            stack.mkdir(), keys.mkdir()
            (stack / "fleet-inventory.yml").write_text(INVENTORY)
            (keys / "vm-info.json").write_text('{"username": "tester"}')
            manifest = qta.build_manifest({
                "stack_dir": str(stack), "key_dir": str(keys),
                "stack_name": "ci", "in_network": False})
        self.assertEqual([(v["name"], v["ssh_port"]) for v in manifest],
                         [("rocm-golden-1", 2222), ("rocm-golden-2", 2223)])
        # The image, not the inventory, says which account exists in it.
        self.assertEqual(manifest[0]["username"], "tester")
        self.assertEqual(manifest[1]["rdma_ip"], "192.168.100.12")
        # Documented in vm-manifest, so there before any alias is assigned.
        self.assertEqual([v["ssh_aliases"] for v in manifest], [[], []])
        json.dumps(manifest)


class Overlay(unittest.TestCase):
    def test_nothing_asked_for_writes_nothing(self):
        with mock.patch.dict(os.environ, {}, clear=True):
            self.assertEqual(qta.overlay_elements(), {})

    def test_inputs_become_elements(self):
        with inputs(vm_count="1", vcpus="4", vmem="6144",
                    fleet="vm-nvme: 2\nernic-tap=false\n# a comment"):
            elements = qta.overlay_elements()
        self.assertEqual(elements, {
            "vm-count": "1", "vm-vcpus": "4", "vm-vmem": "6144",
            "vm-shm-size": "7168m", "vm-nvme": "2", "ernic-tap": "false"})

    def test_a_size_in_fleet_lines_gets_its_shm_and_counts_as_sized(self):
        with inputs(fleet="vm-vmem: 8192"):
            elements = qta.overlay_elements()
        self.assertEqual(elements["vm-shm-size"], "9216m")
        self.assertTrue(qta.sized_by_caller(elements))
        self.assertFalse(qta.sized_by_caller({"vm-count": "2"}))

    def test_fleet_lines_outrank_the_derived_shm(self):
        with inputs(vmem="4096", fleet="vm-shm-size: 8g"):
            self.assertEqual(qta.overlay_elements()["vm-shm-size"], "8g")

    def test_overlay_is_fleet_xml_and_escapes(self):
        root = ET.fromstring(qta.render_overlay(
            {"vm-count": "2", "vm-extra-hostfwd": "a<b&c"}))
        self.assertEqual(root.tag, f"{{{qta.NS_FLEET}}}fleet")
        self.assertEqual(root[1].text, "a<b&c")

    def test_bad_lines_are_refused(self):
        for bad in ("just words", "VM_COUNT: 2", "<vm-count>2</vm-count>"):
            with inputs(fleet=bad), self.assertRaises(qta.Failure):
                qta.overlay_elements()
        with inputs(vm_count="two"), self.assertRaises(qta.Failure):
            qta.overlay_elements()


class InstallSource(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.base = Path(self.tmp.name)
        clear = mock.patch.dict(os.environ, {}, clear=True)
        clear.start()
        self.addCleanup(clear.stop)

    def test_pypi_forms(self):
        for given, want in (("", "qemu-tool>=2.1,<4"), ("latest", "qemu-tool"),
                            ("2.1.0", "qemu-tool==2.1.0"),
                            ("~=2.1", "qemu-tool~=2.1")):
            with inputs(qemu_tool_version=given):
                source = qta.install_source(self.base)
            self.assertEqual((source["kind"], source["spec"]), ("pypi", [want]))

    def test_source_is_installed_from_a_copy(self):
        src = self.base / "checkout" / "qemu"
        (src / "build").mkdir(parents=True)
        with inputs(qemu_tool_source=str(src)), self.assertRaises(qta.Failure):
            qta.install_source(self.base)
        (src / "pyproject.toml").write_text("")
        with inputs(qemu_tool_source=str(src)):
            source = qta.install_source(self.base)
        staged = Path(source["spec"][0])
        self.assertEqual(source["kind"], "source")
        self.assertNotEqual(staged, src)
        self.assertTrue((staged / "pyproject.toml").is_file())
        # Not editable, and nothing a build left behind comes along.
        self.assertNotIn("-e", source["spec"])
        self.assertFalse((staged / "build").exists())

    def test_a_ref_excludes_the_other_two(self):
        for other in ({"qemu_tool_version": "2.1.0"},
                      {"qemu_tool_source": "/somewhere"}):
            with inputs(qemu_tool_ref="main", **other), \
                    self.assertRaises(qta.Failure) as ctx:
                qta.install_source(self.base)
            self.assertIn("qemu-tool-ref and qemu-tool-", str(ctx.exception))

    def test_a_source_still_overrides_a_version(self):
        """What 2.0.0 documented; a workflow relying on it keeps working."""
        import contextlib
        import io
        src = self.base / "checkout" / "qemu"
        src.mkdir(parents=True)
        (src / "pyproject.toml").write_text("")
        out = io.StringIO()
        with inputs(qemu_tool_source=str(src), qemu_tool_version="2.1.0"), \
                contextlib.redirect_stdout(out):
            source = qta.install_source(self.base)
        self.assertEqual(source["kind"], "source")
        self.assertIn("::warning::", out.getvalue())

    def test_the_actions_own_directories_cannot_be_a_stack(self):
        self.assertFalse(qta.STACK_NAME.match(qta.ACTION_OWN.name))

    def test_extra_args_paths_are_taken_against_the_workspace(self):
        got = qta.absolute_paths(
            ["--xml", "ci/o.xml", "--report-dir=out", "--yes", "--xml",
             "/abs/x.xml", "--rdma-duration", "5"], Path("/ws"))
        self.assertEqual(got, ["--xml", "/ws/ci/o.xml", "--report-dir=/ws/out",
                               "--yes", "--xml", "/abs/x.xml",
                               "--rdma-duration", "5"])

    def test_a_checkout_above_is_found_the_way_quick_start_finds_it(self):
        tree = self.base / "co"
        (tree / "ansible" / "playbooks").mkdir(parents=True)
        (tree / "ansible" / "playbooks" / "vm-quickstart.yml").write_text("")
        (tree / "qemu").mkdir()
        (tree / "qemu" / "pyproject.toml").write_text("")
        inside = tree / ".work" / "action" / "ci"
        inside.mkdir(parents=True)
        self.assertEqual(qta.checkout_above(inside), tree.resolve())
        self.assertIsNone(qta.checkout_above(self.base / "elsewhere"))

    def test_ref_is_fetched_at_a_tag_a_branch_or_a_commit(self):
        import subprocess
        origin = self.base / "origin"
        (origin / "qemu").mkdir(parents=True)
        (origin / "qemu" / "pyproject.toml").write_text("[project]\n")
        git = ["git", "-C", str(origin), "-c", "user.name=t",
               "-c", "user.email=t@example.com", "-c", "commit.gpgsign=false",
               "-c", "tag.gpgsign=false"]
        subprocess.run(["git", "init", "-q", "-b", "main", str(origin)], check=True)
        subprocess.run(git + ["add", "-A"], check=True)
        subprocess.run(git + ["commit", "-q", "-m", "one"], check=True)
        subprocess.run(git + ["tag", "v9.9.9"], check=True)
        sha = subprocess.run(git + ["rev-parse", "HEAD"], check=True,
                             capture_output=True, text=True).stdout.strip()
        import contextlib
        import io
        for ref in ("v9.9.9", "main"):
            with inputs(qemu_tool_ref=ref,
                        qemu_tool_repository=f"file://{origin}"), \
                    contextlib.redirect_stdout(io.StringIO()):
                source = qta.install_source(self.base)
            self.assertEqual((source["kind"], source["sha"]), ("ref", sha))
            self.assertTrue((Path(source["spec"][0]) / "pyproject.toml").is_file())
            self.assertTrue((Path(source["checkout"]) / "qemu").is_dir())
        with inputs(qemu_tool_ref="no-such-ref",
                    qemu_tool_repository=f"file://{origin}"), \
                contextlib.redirect_stdout(io.StringIO()), \
                self.assertRaises(qta.Failure):
            qta.install_source(self.base)

    def test_repository_names(self):
        self.assertEqual(qta.repository_url("o/r"), "https://github.com/o/r.git")
        self.assertEqual(qta.repository_url("https://h/x.git"), "https://h/x.git")
        self.assertEqual(qta.repository_url("git@h:o/r.git"), "git@h:o/r.git")


class Fleet(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.dir = Path(self.tmp.name)
        clear = mock.patch.dict(os.environ, {}, clear=True)
        clear.start()
        self.addCleanup(clear.stop)

    def xml(self, name, body):
        path = self.dir / name
        path.write_text(f'<fleet xmlns="{qta.NS_FLEET}">{body}</fleet>')
        return str(path)

    def layers(self, **given):
        import contextlib
        import io
        with inputs(**given), contextlib.redirect_stdout(io.StringIO()), \
                mock.patch.object(qta, "packaged_fleet",
                                  return_value=Path("/shipped/flavor.xml")):
            return qta.fleet_layers("python", given.get("flavor", "default"),
                                    self.dir, qta.overlay_elements())

    def test_a_shipped_flavor_with_an_overlay_file_and_inputs(self):
        over = self.xml("small.xml", "<vm-count>1</vm-count>")
        layers, own = self.layers(xml_overlay=over, vcpus="4")
        self.assertEqual(layers, ["/shipped/flavor.xml", over,
                                  str(self.dir / "overlay.xml")])
        self.assertEqual(own, [over])

    def test_a_fleet_of_your_own_replaces_the_flavor(self):
        mine = self.xml("mine.xml", "<vm-count>3</vm-count>")
        layers, own = self.layers(xml=mine, flavor="helios")
        self.assertEqual(layers, [mine])
        self.assertEqual(own, [mine])

    def test_the_shipped_fleet_alone_is_still_named(self):
        self.assertEqual(self.layers()[0], ["/shipped/flavor.xml"])

    REMOVED_IN_3 = ("qemu-digest", "ernic-digest", "rocjitsu-digest",
                    "backing-digest", "domain-pattern", "prom-port",
                    "loki-port", "vm-backing-shared", "ernic-subnet",
                    "ernic-mac-prefix")

    def test_what_the_action_writes_and_shows_reads_on_qemu_tool_3(self):
        """qemu-tool 3 refuses a fleet that sets one of these ten."""
        root = Path(qta.__file__).parent
        examples = sorted((root / "examples").glob("*.xml"))
        self.assertTrue(examples)
        for example in examples:
            tags = {child.tag.rsplit("}", 1)[-1] for child in
                    qta.ElementTree.parse(example).getroot()}
            self.assertFalse(tags & set(self.REMOVED_IN_3), example.name)
        with mock.patch.dict(os.environ, {}, clear=True), \
                inputs(vm_count="1", vcpus="4", vmem="4096"):
            written = set(qta.overlay_elements())
        self.assertEqual(written, {"vm-count", "vm-vcpus", "vm-vmem",
                                   "vm-shm-size"})
        for other in ("action.yml", ".github/workflows/ci.yml"):
            text = (root / other).read_text()
            for element in self.REMOVED_IN_3:
                self.assertNotIn(element, text, (element, other))

    def test_the_readme_names_the_ten_elements_qemu_tool_3_removed(self):
        """Each of them, and only in the section that says where they went."""
        readme = (Path(qta.__file__).parent / "README.md").read_text()
        guide = readme.split("### From qemu-tool 2.x to 3.x")[1].split(
            "\n## ")[0]
        for element in self.REMOVED_IN_3:
            self.assertIn(f"`<{element}>`", guide, element)
            self.assertNotIn(element, readme.replace(guide, ""), element)

    def test_the_default_range_is_said_the_same_everywhere(self):
        root = Path(qta.__file__).parent
        with mock.patch.dict(os.environ, {}, clear=True):
            spec = qta.install_source(Path("/nonexistent"))["spec"][0]
        self.assertEqual(spec, "qemu-tool>=2.1,<4")
        for name in ("README.md", "action.yml"):
            text = (root / name).read_text()
            self.assertIn(">=2.1,<4", text, name)
            self.assertNotIn(">=2.1,<3", text, name)
        self.assertIn("`>=2.1,<4`", (root / "CHANGELOG.md").read_text())

    def test_sizes_in_the_callers_files(self):
        sized = self.xml("sized.xml", "<vm-vcpus>8</vm-vcpus>")
        plain = self.xml("plain.xml", "<vm-count>2</vm-count>")
        self.assertTrue(qta.files_set_sizes([plain, sized]))
        self.assertFalse(qta.files_set_sizes([plain, "/nonexistent.xml"]))

    def test_gpu_generation(self):
        fleet = {"fleet": {"rocjitsu_config": "gfx1250_mi455x.json"}}
        self.assertEqual(qta.gpu_generation(fleet), "gfx1250")
        self.assertEqual(qta.gpu_generation(
            {"fleet": {"rocjitsu_config": "/etc/x/gfx950_mi300.json"}}), "gfx950")
        self.assertEqual(qta.gpu_generation({"fleet": {}}), "gfx1250")
        self.assertEqual(qta.gpu_generation({}), "gfx1250")
        with inputs(gpu_generation="gfx908"):
            self.assertEqual(qta.gpu_generation(fleet), "gfx908")

    def test_seeding_a_key_of_your_own(self):
        import contextlib
        import io
        import shutil
        import subprocess
        if shutil.which("ssh-keygen") is None:
            self.skipTest("no ssh-keygen")
        key = self.dir / "mykey"
        subprocess.run(["ssh-keygen", "-q", "-t", "ed25519", "-N", "", "-f",
                        str(key)], check=True)
        private = key.read_text()
        state = {"key_dir": str(self.dir / "keys"),
                 "images_dir": str(self.dir / "images")}
        stale = self.dir / "images" / "keys" / "quickstart_id_rsa"
        stale.parent.mkdir(parents=True)
        stale.write_text("old")
        with inputs(ssh_key_file=str(key), ssh_user="tester"), \
                contextlib.redirect_stdout(io.StringIO()):
            qta.seed_key(state, {"backing_ref": "reg/img:v1"})
        keys = self.dir / "keys"
        self.assertEqual((keys / "id_rsa").read_text(), private)
        self.assertEqual((keys / "id_rsa").stat().st_mode & 0o777, 0o600)
        # What makes quick-start skip its own fetch: the same image, recorded.
        self.assertEqual((keys / "image-ref").read_text().strip(), "reg/img:v1")
        self.assertEqual(qta.image_username(keys), "tester")
        self.assertFalse(stale.exists())
        with inputs(ssh_user="tester"), self.assertRaises(qta.Failure):
            qta.seed_key(state, {})
        # The public half given by mistake, or a key with a passphrase, is
        # refused here, where the reason can still be said.
        locked = self.dir / "locked"
        subprocess.run(["ssh-keygen", "-q", "-t", "ed25519", "-N", "secret",
                        "-f", str(locked)], check=True)
        for bad in (f"{key}.pub", str(locked)):
            with inputs(ssh_key_file=bad), self.assertRaises(qta.Failure) as ctx:
                qta.seed_key(state, {})
            self.assertIn("not a private key", str(ctx.exception))


VMS = [{"name": f"g-{i}", "index": i, "ssh_host": "127.0.0.1",
        "ssh_port": 2221 + i, "username": "ubuntu",
        "ssh_key_file": "/k/id_rsa", "ssh_cmd": "",
        "rdma_ip": f"192.168.100.{10 + i}",
        "rdma_ips": [f"192.168.100.{10 + i}"], "nics": [],
        "rdma_device": "rocm-rdma-ernic0", "gpu": "loaded"}
       for i in (1, 2, 3)]


class Guests(unittest.TestCase):
    def test_select(self):
        names = lambda spec: [v["name"] for v in qta.select(VMS, spec)]  # noqa: E731
        self.assertEqual(names("all"), ["g-1", "g-2", "g-3"])
        self.assertEqual(names(""), ["g-1", "g-2", "g-3"])
        self.assertEqual(names("first"), ["g-1"])
        self.assertEqual(names("last"), ["g-3"])
        self.assertEqual(names("3, g-1"), ["g-3", "g-1"])
        self.assertEqual(names("1,"), ["g-1"])
        with self.assertRaises(qta.Failure):
            qta.select(VMS, "9")

    def test_script_environment(self):
        with mock.patch.dict(os.environ, {}, clear=True), \
                inputs(env="MODE=a b\nN=1"):
            text = qta.guest_script(VMS[1], VMS, "make test", "~/workspace")
        self.assertIn("export QT_VM_INDEX=2\n", text)
        self.assertIn("export QT_PEER_RDMA_IPS='192.168.100.11 192.168.100.13'\n", text)
        self.assertIn("export QT_VM_1_RDMA_IP=192.168.100.11\n", text)
        self.assertIn("export MODE='a b'\n", text)
        self.assertIn("\ncd workspace\nmake test\n", text)

    def test_remote_paths(self):
        self.assertEqual(qta.remote_path("~/a b"), "'a b'")
        self.assertEqual(qta.remote_path("~"), ".")
        self.assertEqual(qta.remote_path("/opt/x"), "/opt/x")

    def test_copy_destinations(self):
        with tempfile.TemporaryDirectory() as tmp:
            file = Path(tmp, "f.txt")
            file.write_text("x")
            self.assertEqual(qta.parse_copy(tmp)[1], "workspace")
            self.assertEqual(qta.parse_copy(str(file))[1], ".")
            self.assertEqual(qta.parse_copy(f"{tmp}:src/app")[1], "src/app")
            with self.assertRaises(qta.Failure):
                qta.parse_copy(str(Path(tmp, "absent")))

    def test_ssh_config_and_inventory(self):
        with tempfile.TemporaryDirectory() as tmp:
            config, inventory = Path(tmp, "c"), Path(tmp, "i")
            qta.write_ssh_config(VMS, config)
            qta.write_inventory(VMS, inventory)
            self.assertIn("Host g-2 vm2\n  HostName 127.0.0.1\n  Port 2223\n",
                          config.read_text())
            self.assertEqual(config.stat().st_mode & 0o777, 0o600)
            self.assertIn("    g-3:\n      ansible_host: 127.0.0.1\n"
                          "      ansible_port: 2224\n", inventory.read_text())


def silently(function, *args, **kwargs):
    """Call, and return what it returned and what it printed."""
    import contextlib
    import io
    out = io.StringIO()
    with contextlib.redirect_stdout(out):
        result = function(*args, **kwargs)
    return result, out.getvalue()


def guests(*statuses):
    return [dict(VMS[i], gpu=None, name=f"g-{i + 1}")
            for i in range(len(statuses))]


class GpuModes(unittest.TestCase):
    """The gpu input: what each value does with each amdgpu-probe status."""

    def probe(self, vms, *rounds):
        """gpu_status answering each round of statuses in guest order."""
        answers = iter([word for statuses in rounds for word in statuses])
        return mock.patch.object(qta, "gpu_status",
                                 side_effect=lambda vm: next(answers))

    def bring_up(self, fail=()):
        def one(vm, _tar, _fwset):
            if vm["name"] in fail:
                raise qta.Failure(f"{vm['name']}: amdgpu did not bind the "
                                  "emulated GPU")
        stack = mock.patch.multiple(
            qta,
            read_inventory=mock.Mock(return_value=(
                {"fleet_guest_rocjitsu_image": "img"}, [])),
            firmware_set=mock.Mock(return_value="gap"),
            generate_firmware=mock.Mock(),
            bring_up_gpu=mock.Mock(side_effect=one))
        return stack

    def test_the_input(self):
        for given, want in (("", "true"), ("true", "true"), ("yes", "true"),
                            ("false", "false"), ("0", "false"),
                            ("required", "required"), ("Optional", "optional")):
            with mock.patch.dict(os.environ, {}, clear=True), inputs(gpu=given):
                self.assertEqual(qta.gpu_mode(), want, given)
        with inputs(gpu="strict"), self.assertRaises(qta.Failure) as ctx:
            qta.gpu_mode()
        self.assertIn("required or optional", str(ctx.exception))

    def test_true_leaves_a_guest_without_a_gpu_alone(self):
        """As before the modes existed: absent and unknown are no failure."""
        vms = guests("absent", "unknown", "loaded")
        with self.probe(vms, ("absent", "unknown", "loaded")):
            silently(qta.setup_gpus, {}, vms)
